-- Development fixture for schema 010 only; never startup/deploy automatically.
-- Invoke psql -X -1 -v ON_ERROR_STOP=1 -f db/seeds/mock_data.sql.
-- Fictional accounts share KicauMock2026!; Argon2id hashes match the application.
DO $schema$
BEGIN
 IF to_regclass('iam.user_master_history') IS NULL OR to_regclass('asset.bird_master_history') IS NULL
 OR EXISTS(SELECT FROM unnest(ARRAY['ADMIN','OPERATOR','JURI','PESERTA']) role(name) WHERE NOT EXISTS(SELECT FROM iam.roles r WHERE r.name=role.name)) THEN
  RAISE EXCEPTION 'Mock seed requires migrations through 010';
 END IF;
END $schema$;
CREATE TEMP TABLE _kicau_mock_expected(entity text NOT NULL,id uuid PRIMARY KEY,identity jsonb NOT NULL,payload jsonb NOT NULL) ON COMMIT DROP;
SELECT pg_advisory_xact_lock(753122);

-- Existing identity must match; edits/passwords/status/versions are never reset.
DO $identities$
DECLARE fixture record; actual jsonb; role_id uuid;
BEGIN
 FOR fixture IN SELECT * FROM _kicau_mock_expected LOOP
  EXECUTE format('SELECT to_jsonb(t) FROM %s t WHERE id=$1',fixture.entity::regclass) INTO actual USING fixture.id;
  IF actual IS NOT NULL AND NOT actual @> fixture.identity THEN RAISE EXCEPTION 'Fixture identity collision: %, %',fixture.entity,fixture.id; END IF;
  IF fixture.payload ? '_role' THEN
   SELECT id INTO STRICT role_id FROM iam.roles WHERE name=fixture.payload->>'_role';
   IF actual IS NOT NULL AND actual->>'role_id'<>role_id::text THEN RAISE EXCEPTION 'Fixture role collision: %, %',fixture.entity,fixture.id; END IF;
  END IF;
 END LOOP;
END $identities$;
SELECT set_config('app.actor_id','6d6f636b-0001-4000-8000-000000000001',true);
SELECT set_config('app.arena_id','',true);
DO $insert$
DECLARE fixture record; columns_sql text; payload jsonb; role_id uuid;
BEGIN
 FOR fixture IN SELECT * FROM _kicau_mock_expected ORDER BY
  CASE entity WHEN 'iam.users' THEN 1 WHEN 'asset.arenas' THEN 2 WHEN 'asset.bird_species' THEN 3
   WHEN 'asset.gantangan' THEN 4 WHEN 'competition.events' THEN 5 WHEN 'competition.categories' THEN 6
   WHEN 'judging.score_criteria' THEN 7 WHEN 'competition.rounds' THEN 8 WHEN 'asset.birds' THEN 9
   WHEN 'asset.bird_ownership_history' THEN 10 ELSE 11 END,id
 LOOP
  -- Important: do not issue even a conflicting INSERT for existing masters:
  -- BEFORE INSERT triggers run before ON CONFLICT and require a valid actor.
  EXECUTE format('SELECT to_jsonb(t) FROM %s t WHERE id=$1',fixture.entity::regclass) INTO payload USING fixture.id;
  IF payload IS NOT NULL THEN CONTINUE; END IF;
  payload:=fixture.payload;
  IF payload ? '_role' THEN
   SELECT id INTO STRICT role_id FROM iam.roles WHERE name=payload->>'_role';
   payload:=(payload-'_role')||jsonb_build_object('role_id',role_id);
  END IF;
  SELECT string_agg(format('%I',key),',' ORDER BY key) INTO columns_sql FROM jsonb_object_keys(payload) key;
  EXECUTE format('INSERT INTO %s(%s) SELECT %s FROM jsonb_populate_record(NULL::%s,$1)',fixture.entity::regclass,columns_sql,columns_sql,fixture.entity::regclass) USING payload;
 END LOOP;
END $insert$;
SELECT pg_advisory_xact_lock(753120);
REFRESH MATERIALIZED VIEW cloud_read.mv_round_score_summary;
UPDATE cloud_read.refresh_status SET snapshot_at=CURRENT_TIMESTAMP,refreshed_at=clock_timestamp() WHERE view_name='mv_round_score_summary';
